import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const OUT = join(ROOT, 'data', 'life.json');

const ORIGIN = { lat: 41.1496, lon: -8.611 }; // cities/porto.json origin
const M_PER_DEG_LAT = 110574;
const M_PER_DEG_LON = 111320;
const r6 = (v) => Math.round(v * 1e6) / 1e6;
const cos0 = Math.cos((ORIGIN.lat * Math.PI) / 180);
const dist = (a, b) => Math.hypot((a[0] - b[0]) * M_PER_DEG_LAT, (a[1] - b[1]) * M_PER_DEG_LON * cos0);
const length = (l) => l.slice(1).reduce((s, p, i) => s + dist(l[i], p), 0);

